using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Coordinates;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Positional;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Validation.OrbitalAndPositional;
public sealed class AstronomySpatialReferenceContextValidationRuleTests { [Fact] public void Valid_spatial_context_passes() => Assert.Empty(new AstronomySpatialReferenceContextValidationRule().Validate(OrbitalPositionalValidationFixture.AngularPayload(), OrbitalPositionalValidationFixture.Context())); [Fact] public void Horizontal_requires_topocentric_origin() { var payload = new Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Positional.AstronomySpatialPositionPayload(new("typed.positional.spatial-position.v1"), new Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Positional.AstronomySpatialPosition(OrbitalPositionalValidationFixture.SpatialContext(AstronomyCoordinateSystem.Horizontal, AstronomyReferenceOrigin.Geocentric), ((Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Positional.AstronomyAngularPositionValue)OrbitalPositionalValidationFixture.AngularPayload().Position.Value))); Assert.Contains(new AstronomySpatialReferenceContextValidationRule().Validate(payload, OrbitalPositionalValidationFixture.Context()), i => i.Code == AstronomyPositionalValidationCodes.CoordinateSystemMismatch); } }
